function validate([n, logs, x, queries]) {
  if (!Number.isInteger(n) || n < 1 || n > 100000) return 'n is between 1 and 10^5.';
  if (!Array.isArray(logs) || logs.length < 1 || logs.length > 100000) return 'logs needs 1 to 10^5 entries.';
  if (logs.some(e => !Array.isArray(e) || e.length !== 2 || !Number.isInteger(e[0]) || !Number.isInteger(e[1]))) return 'Each log is a pair [server_id, time].';
  if (logs.some(([id]) => id < 1 || id > n)) return 'Each server_id is between 1 and n.';
  if (logs.some(([, time]) => time < 1 || time > 1e6)) return 'Each log time is between 1 and 10^6.';
  if (!Number.isInteger(x) || x < 1 || x > 100000) return 'x is between 1 and 10^5.';
  if (!Array.isArray(queries) || queries.length < 1 || queries.length > 100000) return 'queries needs 1 to 10^5 values.';
  if (queries.some(q => !Number.isInteger(q) || q <= x || q > 1e6)) return 'Each query is greater than x and at most 10^6.';
  return null;
}

