function countServers(n, logs, x, queries) {
  logs.sort((a, b) => a[1] - b[1]);
  const order = queries.map((_, i) => i).sort((a, b) => queries[a] - queries[b]);
  const hits = new Array(n + 1).fill(0);
  const answer = new Array(queries.length).fill(0);
  let active = 0;
  let left = 0;
  let right = 0;

  for (const index of order) {
    const end = queries[index];
    const start = end - x;
    while (right < logs.length && logs[right][1] <= end) {
      const server = logs[right][0];
      if (hits[server] === 0) {
        active++;
      }
      hits[server]++;
      right++;
    }
    while (left < right && logs[left][1] < start) {
      const server = logs[left][0];
      hits[server]--;
      if (hits[server] === 0) {
        active--;
      }
      left++;
    }
    answer[index] = n - active;
  }
  return answer;
}

