function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'small') {
    const n = int(1, 6);
    const maxTime = int(3, 25);
    const x = int(1, Math.min(6, maxTime - 1));
    const logs = Array.from({ length: int(1, 10) }, () => [int(1, n), int(1, maxTime)]);
    const queries = Array.from({ length: int(1, 6) }, () => int(x + 1, maxTime + 3));
    return [n, logs, x, queries];
  }
  const n = rand() < 0.3 ? 100000 : int(1, 1500);
  const maxTime = rand() < 0.5 ? 1000000 : 20000;
  const x = rand() < 0.5 ? int(1, Math.floor(maxTime / 20)) : int(1, Math.min(100000, maxTime - 1));
  const logs = Array.from({ length: 2000 }, () => [int(1, n), int(1, maxTime)]);
  const queries = Array.from({ length: 2000 }, () => int(x + 1, maxTime));
